{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action is taken to resolve a failure or error reported by an earlier execution step.",
      "source_description": "An earlier observed execution failure or error result.",
      "target_description": "A subsequent agent action intended to resolve that failure."
    },
    {
      "name": "RETRIES_PREVIOUSLY_FAILED_ACTION",
      "definition": "After the cause of a prior failure has been addressed, the agent re-executes the same operation that previously failed.",
      "source_description": "An earlier agent action that failed to produce a result.",
      "target_description": "A later re-execution of that same action."
    },
    {
      "name": "REVISES_APPROACH_BASED_ON_OBSERVED_RESULT",
      "definition": "An observed execution result reveals that an earlier assumption or approach was incorrect, prompting the agent to modify its artifact or plan accordingly.",
      "source_description": "An observed execution result that contradicts or invalidates a prior assumption.",
      "target_description": "A subsequent agent action or artifact that corrects the earlier approach."
    },
    {
      "name": "USES_OBSERVED_INFORMATION_AS_INPUT",
      "definition": "The agent incorporates information obtained from an earlier tool output into a subsequent action, using an observed value as an argument, filter, or parameter.",
      "source_description": "An earlier tool observation containing information needed for later processing.",
      "target_description": "A subsequent agent action that consumes that information."
    },
    {
      "name": "VERIFIES_OUTPUT_OF_PRIOR_ACTION",
      "definition": "A subsequent agent action inspects or validates an artifact produced by an earlier action to confirm it contains the expected content.",
      "source_description": "An earlier agent action that produced an artifact or result.",
      "target_description": "A subsequent inspection or validation action."
    }
  ]
}

